import { registerBlockType } from "@wordpress/blocks";

registerBlockType("ourblocktheme/schoolmotto", {
  title: "School Motto",
  attributes: {
    videoURL: { type: "string" },
  },
  edit: EditComponent,
  save: SaveComponent,
});

function EditComponent() {
  return (
    <div class="motto">
      <svg width="300" height="120" xmlns="http://www.w3.org/2000/svg">
        <text
          x="100"
          y="56"
          fill="#d00000"
          font-weight="500"
          font-family="Teko"
          font-size="48"
          fon-style="oblique"
        >
          NO GRIT,
        </text>
        <text
          x="0"
          y="105"
          fill="#d00000"
          font-weight="500"
          font-family="Teko"
          font-size="48"
        >
          NO GREATNESS.
        </text>
      </svg>
    </div>
  );
}

